package org.icu.sepsis.timeline;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;
import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;import org.springframework.security.core.Authentication;import org.icu.sepsis.domain.Domain.*;import org.icu.sepsis.application.Store;import org.icu.sepsis.ai.AiAssistService;import org.icu.sepsis.api.ApiException;
class ClinicalTimelineControllerTest {
 final Store store=mock(Store.class);final ClinicalTimelineService service=mock(ClinicalTimelineService.class);final AiAssistService ai=mock(AiAssistService.class);final ClinicalTimelineController controller=new ClinicalTimelineController(store,service,ai);final Instant end=Instant.parse("2026-11-06T00:00:00Z");
 ClinicalTimelineService.Packet packet(){var p=new ClinicalTimelineService.Packet();p.from=end.minusSeconds(7200);p.asOf=end;p.mode="retrospective";return p;}
 @Test void exactDragRangeIsTrimmedAndOnlySelectedMedicationNamesReachAi(){var patient=new Patient();patient.id="p";var packet=packet();for(String name:List.of("合成甲药","合成乙药")){var e=new ClinicalTimelineService.Event();e.name=name;e.time=end.minusSeconds(600);e.action="执行";packet.medications.add(e);}when(store.patient("p")).thenReturn(patient);when(service.read(eq(patient),eq(2),eq(end),eq("retrospective"))).thenReturn(packet);when(ai.timelineBrief(any(),anyList(),any(),any(),anyString(),anyList(),anyString())).thenReturn(Map.of());var request=new ClinicalTimelineController.Request();request.hours=2;request.end=end;request.start=end.minusSeconds(5400);request.codes=List.of("HR");request.medicationNames=List.of("合成甲药");var auth=mock(Authentication.class);when(auth.getName()).thenReturn("synthetic-user");controller.analyze("p",request,auth);assertEquals(request.start,packet.from);assertEquals(1,packet.medications.size());verify(ai).timelineBrief(eq(patient),argThat(facts->facts.stream().noneMatch(f->f[1].contains("合成乙药"))),eq(request.start),eq(end),eq("retrospective"),eq(List.of("HR")),eq("synthetic-user"));}
 @Test void invalidStartCannotInvokeAi(){var patient=new Patient();when(store.patient("p")).thenReturn(patient);when(service.read(any(),anyInt(),any(),anyString())).thenReturn(packet());var request=new ClinicalTimelineController.Request();request.hours=2;request.end=end;request.start=end.minusSeconds(7201);request.codes=List.of("HR");assertThrows(ApiException.class,()->controller.analyze("p",request,mock(Authentication.class)));verifyNoInteractions(ai);}
 @Test void unauthorizedPatientFailureStopsBeforeSourceRead(){when(store.patient("foreign")).thenThrow(ApiException.notFound());assertThrows(ApiException.class,()->controller.read("foreign",24,end,"retrospective"));verifyNoInteractions(service,ai);}
}
